CREATE TABLE training_projects(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),code TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,code),UNIQUE(id,store_id));
CREATE TABLE training_project_versions(project_id TEXT NOT NULL,store_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(version>=1),name TEXT NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),description TEXT NOT NULL CHECK(length(trim(description)) BETWEEN 1 AND 1000),instructions TEXT NOT NULL CHECK(length(trim(instructions)) BETWEEN 1 AND 1000),status TEXT NOT NULL CHECK(status IN('active','inactive')),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 300),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(project_id,version),UNIQUE(project_id,version,store_id),FOREIGN KEY(project_id,store_id) REFERENCES training_projects(id,store_id));
CREATE TABLE training_plans(id TEXT PRIMARY KEY,store_id TEXT NOT NULL REFERENCES stores(id),customer_id TEXT NOT NULL REFERENCES customers(id),cycle_id TEXT NOT NULL,cycle_version INTEGER NOT NULL,visit_id TEXT REFERENCES visits(id),context_basis TEXT NOT NULL CHECK(context_basis IN('cycle','visit_cycle')),serial INTEGER NOT NULL CHECK(serial>=1),plan_number TEXT NOT NULL UNIQUE,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(store_id,serial),UNIQUE(id,customer_id,store_id),FOREIGN KEY(cycle_id,cycle_version,customer_id) REFERENCES cycle_versions(cycle_id,version,customer_id),CHECK((context_basis='cycle' AND visit_id IS NULL) OR (context_basis='visit_cycle' AND visit_id IS NOT NULL)));
CREATE TABLE training_plan_versions(plan_id TEXT NOT NULL REFERENCES training_plans(id),version INTEGER NOT NULL CHECK(version>=1),title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 120),assessment TEXT NOT NULL CHECK(length(trim(assessment)) BETWEEN 1 AND 1000),goals TEXT NOT NULL CHECK(length(trim(goals)) BETWEEN 1 AND 1000),frequency_note TEXT CHECK(length(frequency_note)<=300),duration_note TEXT CHECK(length(duration_note)<=300),reassessment_note TEXT CHECK(length(reassessment_note)<=1000),owner_id TEXT NOT NULL REFERENCES users(id),source TEXT NOT NULL CHECK(source IN('staff_record','external_transcript','customer_transcript')),source_note TEXT NOT NULL CHECK(length(trim(source_note)) BETWEEN 1 AND 1000),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 300),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),PRIMARY KEY(plan_id,version));
CREATE TABLE training_plan_items(plan_id TEXT NOT NULL,version INTEGER NOT NULL,position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 30),project_id TEXT NOT NULL,project_version INTEGER NOT NULL,instructions TEXT NOT NULL CHECK(length(trim(instructions)) BETWEEN 1 AND 1000),PRIMARY KEY(plan_id,version,position),FOREIGN KEY(plan_id,version) REFERENCES training_plan_versions(plan_id,version),FOREIGN KEY(project_id,project_version) REFERENCES training_project_versions(project_id,version));
CREATE TABLE training_plan_documents(plan_id TEXT NOT NULL,version INTEGER NOT NULL,document_version_id TEXT NOT NULL REFERENCES document_versions(id),PRIMARY KEY(plan_id,version,document_version_id),FOREIGN KEY(plan_id,version) REFERENCES training_plan_versions(plan_id,version));
CREATE TABLE training_plan_attachments(plan_id TEXT NOT NULL,version INTEGER NOT NULL,attachment_id TEXT NOT NULL REFERENCES attachments(id),PRIMARY KEY(plan_id,version,attachment_id),FOREIGN KEY(plan_id,version) REFERENCES training_plan_versions(plan_id,version));
CREATE TABLE training_plan_events(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES training_plans(id),revision INTEGER NOT NULL CHECK(revision>=1),plan_version INTEGER NOT NULL,session_sequence INTEGER NOT NULL CHECK(session_sequence>=0),action TEXT NOT NULL CHECK(action IN('create','revise','confirm','pause','resume','end')),status TEXT NOT NULL CHECK(status IN('draft','active','paused','ended')),note TEXT NOT NULL CHECK(length(trim(note)) BETWEEN 1 AND 1000),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 300),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(plan_id,revision),FOREIGN KEY(plan_id,plan_version) REFERENCES training_plan_versions(plan_id,version));
CREATE TABLE training_sessions(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL,plan_version INTEGER NOT NULL,customer_id TEXT NOT NULL,store_id TEXT NOT NULL,cycle_id TEXT NOT NULL,visit_id TEXT NOT NULL REFERENCES visits(id),visit_cycle_version INTEGER NOT NULL,plan_revision INTEGER NOT NULL,serial INTEGER NOT NULL CHECK(serial>=1),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(plan_id,serial),FOREIGN KEY(plan_id,plan_version) REFERENCES training_plan_versions(plan_id,version),FOREIGN KEY(plan_id,customer_id,store_id) REFERENCES training_plans(id,customer_id,store_id),FOREIGN KEY(cycle_id,visit_cycle_version,customer_id) REFERENCES cycle_versions(cycle_id,version,customer_id),FOREIGN KEY(visit_id,cycle_id,customer_id) REFERENCES visit_cycles(visit_id,cycle_id,customer_id));
CREATE TABLE training_session_events(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES training_sessions(id),plan_id TEXT NOT NULL REFERENCES training_plans(id),revision INTEGER NOT NULL CHECK(revision>=1),sequence INTEGER NOT NULL CHECK(sequence>=1),plan_revision INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('create','assign','start','pause','resume','record','correct','confirm','abort','note')),status TEXT NOT NULL CHECK(status IN('ready','running','paused','recorded','reviewed','aborted')),assignee_id TEXT NOT NULL REFERENCES users(id),started_at TEXT,manifest_json TEXT CHECK(manifest_json IS NULL OR json_valid(manifest_json)),note TEXT NOT NULL CHECK(length(trim(note)) BETWEEN 1 AND 1000),reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 300),created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),UNIQUE(session_id,revision),UNIQUE(plan_id,sequence),FOREIGN KEY(plan_id,plan_revision) REFERENCES training_plan_events(plan_id,revision));
CREATE VIEW training_plan_current AS SELECT p.*,v.version,v.title,v.owner_id,e.revision,e.status,e.created_at event_created_at,COALESCE((SELECT max(sequence) FROM training_session_events WHERE plan_id=p.id),0) session_sequence FROM training_plans p JOIN training_plan_versions v ON v.plan_id=p.id AND v.version=(SELECT max(version) FROM training_plan_versions WHERE plan_id=p.id) JOIN training_plan_events e ON e.plan_id=p.id AND e.revision=(SELECT max(revision) FROM training_plan_events WHERE plan_id=p.id);
CREATE VIEW training_session_current AS SELECT s.*,e.revision,e.sequence,e.status,e.assignee_id,e.started_at,e.manifest_json,e.created_at event_created_at FROM training_sessions s JOIN training_session_events e ON e.session_id=s.id AND e.revision=(SELECT max(revision) FROM training_session_events WHERE session_id=s.id);
CREATE TRIGGER training_project_ready BEFORE INSERT ON training_projects BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security sec ON sec.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND COALESCE(sec.must_change_password,0)=0 AND u.role IN('manager','professional')) OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(NEW.created_at)<>24 THEN RAISE(ABORT,'training project actor invalid') END;END;
CREATE TRIGGER training_project_version_ready BEFORE INSERT ON training_project_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security sec ON sec.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND COALESCE(sec.must_change_password,0)=0 AND u.role IN('manager','professional')) OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(NEW.created_at)<>24 OR NEW.version<>COALESCE((SELECT max(version)+1 FROM training_project_versions WHERE project_id=NEW.project_id),1) OR NEW.created_at<(SELECT created_at FROM training_projects WHERE id=NEW.project_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM training_project_versions WHERE project_id=NEW.project_id),'') THEN RAISE(ABORT,'training project version invalid') END;END;
CREATE TRIGGER training_plan_ready BEFORE INSERT ON training_plans BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security sec ON sec.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND COALESCE(sec.must_change_password,0)=0 AND u.role IN('professional')) OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(NEW.created_at)<>24 OR NEW.serial<>COALESCE((SELECT max(serial)+1 FROM training_plans WHERE store_id=NEW.store_id),1) OR NOT EXISTS(SELECT 1 FROM customers c JOIN cycle_versions v ON v.customer_id=c.id WHERE c.id=NEW.customer_id AND c.store_id=NEW.store_id AND v.cycle_id=NEW.cycle_id AND v.version=NEW.cycle_version AND v.type='training' AND NEW.created_at>=v.created_at) OR (NEW.visit_id IS NULL AND NEW.cycle_version<>(SELECT max(version) FROM cycle_versions WHERE cycle_id=NEW.cycle_id)) OR (NEW.visit_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM visit_cycle_versions r JOIN visits v ON v.id=r.visit_id WHERE r.visit_id=NEW.visit_id AND r.cycle_id=NEW.cycle_id AND r.customer_id=NEW.customer_id AND r.basis='captured' AND r.version=NEW.cycle_version AND v.store_id=NEW.store_id AND NEW.created_at>=v.created_at)) THEN RAISE(ABORT,'training plan context invalid') END;END;
CREATE TRIGGER training_plan_version_ready BEFORE INSERT ON training_plan_versions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security sec ON sec.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=(SELECT store_id FROM training_plans WHERE id=NEW.plan_id) AND COALESCE(sec.must_change_password,0)=0 AND u.role IN('professional')) OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(NEW.created_at)<>24 OR NEW.version<>COALESCE((SELECT max(version)+1 FROM training_plan_versions WHERE plan_id=NEW.plan_id),1) OR NEW.created_at<(SELECT created_at FROM training_plans WHERE id=NEW.plan_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM training_plan_events WHERE plan_id=NEW.plan_id),'') OR (SELECT status FROM training_plan_current WHERE id=NEW.plan_id)='ended' OR EXISTS(SELECT 1 FROM training_plan_versions v WHERE v.plan_id=NEW.plan_id AND NOT EXISTS(SELECT 1 FROM training_plan_events e WHERE e.plan_id=v.plan_id AND e.plan_version=v.version AND e.action IN('create','revise'))) OR NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.owner_id AND u.role='professional' AND u.active=1 AND u.store_id=(SELECT store_id FROM training_plans WHERE id=NEW.plan_id) AND COALESCE(s.must_change_password,0)=0) OR json_type(NEW.manifest_json,'$.items') IS NOT 'array' OR json_array_length(NEW.manifest_json,'$.items') NOT BETWEEN 1 AND 30 OR json_array_length(NEW.manifest_json,'$.document_version_ids')>10 OR json_array_length(NEW.manifest_json,'$.attachment_ids')>10 OR json_type(NEW.manifest_json,'$.document_version_ids') IS NOT 'array' OR json_type(NEW.manifest_json,'$.attachment_ids') IS NOT 'array' THEN RAISE(ABORT,'training plan version invalid') END;END;
CREATE TRIGGER training_plan_item_ready BEFORE INSERT ON training_plan_items BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM training_plan_events WHERE plan_id=NEW.plan_id AND plan_version=NEW.version) OR NEW.position<>COALESCE((SELECT max(position)+1 FROM training_plan_items WHERE plan_id=NEW.plan_id AND version=NEW.version),1) OR NOT EXISTS(SELECT 1 FROM training_project_versions v JOIN training_plan_versions p ON p.plan_id=NEW.plan_id AND p.version=NEW.version JOIN json_each(p.manifest_json,'$.items') x ON json_extract(x.value,'$.position')=NEW.position WHERE v.project_id=NEW.project_id AND v.version=NEW.project_version AND v.store_id=(SELECT store_id FROM training_plans WHERE id=NEW.plan_id) AND json_extract(x.value,'$.project_id')=NEW.project_id AND json_extract(x.value,'$.project_version')=NEW.project_version AND json_extract(x.value,'$.instructions')=NEW.instructions AND ((v.status='active' AND v.version=(SELECT max(version) FROM training_project_versions WHERE project_id=v.project_id)) OR EXISTS(SELECT 1 FROM training_plan_items old WHERE old.plan_id=NEW.plan_id AND old.version=NEW.version-1 AND old.project_id=v.project_id AND old.project_version=v.version))) THEN RAISE(ABORT,'training item source invalid') END;END;
CREATE TRIGGER training_plan_document_ready BEFORE INSERT ON training_plan_documents BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM training_plan_events WHERE plan_id=NEW.plan_id AND plan_version=NEW.version) OR NOT EXISTS(SELECT 1 FROM document_versions d JOIN training_plans p ON p.id=NEW.plan_id JOIN training_plan_versions v ON v.plan_id=p.id AND v.version=NEW.version JOIN json_each(v.manifest_json,'$.document_version_ids') x ON x.value=d.id WHERE d.id=NEW.document_version_id AND d.customer_id=p.customer_id) THEN RAISE(ABORT,'training evidence invalid') END;END;
CREATE TRIGGER training_plan_attachment_ready BEFORE INSERT ON training_plan_attachments BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM training_plan_events WHERE plan_id=NEW.plan_id AND plan_version=NEW.version) OR NOT EXISTS(SELECT 1 FROM attachments d JOIN training_plans p ON p.id=NEW.plan_id JOIN training_plan_versions v ON v.plan_id=p.id AND v.version=NEW.version JOIN json_each(v.manifest_json,'$.attachment_ids') x ON x.value=d.id WHERE d.id=NEW.attachment_id AND d.customer_id=p.customer_id AND d.revoked_at IS NULL) THEN RAISE(ABORT,'training evidence invalid') END;END;
CREATE TRIGGER training_plan_event_ready BEFORE INSERT ON training_plan_events BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security sec ON sec.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=(SELECT store_id FROM training_plans WHERE id=NEW.plan_id) AND COALESCE(sec.must_change_password,0)=0 AND u.role IN('professional')) OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(NEW.created_at)<>24 OR NEW.revision<>COALESCE((SELECT max(revision)+1 FROM training_plan_events WHERE plan_id=NEW.plan_id),1) OR NEW.session_sequence<>COALESCE((SELECT max(sequence) FROM training_session_events WHERE plan_id=NEW.plan_id),0) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM training_plan_events WHERE plan_id=NEW.plan_id),'') OR NEW.created_at<COALESCE((SELECT max(created_at) FROM training_session_events WHERE plan_id=NEW.plan_id),'') OR NEW.plan_version<>(SELECT max(version) FROM training_plan_versions WHERE plan_id=NEW.plan_id) OR NOT(NEW.action IN('create','revise') AND NEW.status='draft' AND NEW.plan_version=(SELECT max(version) FROM training_plan_versions WHERE plan_id=NEW.plan_id) AND NEW.created_at=(SELECT created_at FROM training_plan_versions WHERE plan_id=NEW.plan_id AND version=NEW.plan_version) AND NEW.created_by=(SELECT created_by FROM training_plan_versions WHERE plan_id=NEW.plan_id AND version=NEW.plan_version) AND ((NEW.action='create' AND NEW.revision=1 AND NEW.plan_version=1) OR (NEW.action='revise' AND NEW.revision>1 AND (SELECT status FROM training_plan_events WHERE plan_id=NEW.plan_id ORDER BY revision DESC LIMIT 1)<>'ended' AND NEW.plan_version=(SELECT max(plan_version)+1 FROM training_plan_events WHERE plan_id=NEW.plan_id))) OR NEW.action='confirm' AND (SELECT status FROM training_plan_events WHERE plan_id=NEW.plan_id ORDER BY revision DESC LIMIT 1)='draft' AND NEW.status='active' OR NEW.action='pause' AND (SELECT status FROM training_plan_events WHERE plan_id=NEW.plan_id ORDER BY revision DESC LIMIT 1)='active' AND NEW.status='paused' OR NEW.action='resume' AND (SELECT status FROM training_plan_events WHERE plan_id=NEW.plan_id ORDER BY revision DESC LIMIT 1)='paused' AND NEW.status='active' OR NEW.action='end' AND (SELECT status FROM training_plan_events WHERE plan_id=NEW.plan_id ORDER BY revision DESC LIMIT 1) IN('draft','active','paused') AND NEW.status='ended' AND NOT EXISTS(SELECT 1 FROM training_session_current WHERE plan_id=NEW.plan_id AND status IN('ready','running','paused'))) OR (NEW.action IN('confirm','pause','resume','end') AND NEW.created_by<>(SELECT owner_id FROM training_plan_versions WHERE plan_id=NEW.plan_id AND version=NEW.plan_version)) OR (NEW.action IN('create','revise') AND ((SELECT count(*) FROM training_plan_items WHERE plan_id=NEW.plan_id AND version=NEW.plan_version)<>json_array_length((SELECT manifest_json FROM training_plan_versions WHERE plan_id=NEW.plan_id AND version=NEW.plan_version),'$.items') OR (SELECT count(*) FROM training_plan_documents WHERE plan_id=NEW.plan_id AND version=NEW.plan_version)<>json_array_length((SELECT manifest_json FROM training_plan_versions WHERE plan_id=NEW.plan_id AND version=NEW.plan_version),'$.document_version_ids') OR (SELECT count(*) FROM training_plan_attachments WHERE plan_id=NEW.plan_id AND version=NEW.plan_version)<>json_array_length((SELECT manifest_json FROM training_plan_versions WHERE plan_id=NEW.plan_id AND version=NEW.plan_version),'$.attachment_ids'))) OR (NEW.action IN('confirm','resume') AND EXISTS(SELECT 1 FROM training_plan_attachments r JOIN attachments a ON a.id=r.attachment_id WHERE r.plan_id=NEW.plan_id AND r.version=NEW.plan_version AND a.revoked_at IS NOT NULL)) THEN RAISE(ABORT,'training plan event invalid') END;END;
CREATE TRIGGER training_session_ready BEFORE INSERT ON training_sessions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security sec ON sec.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=NEW.store_id AND COALESCE(sec.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(NEW.created_at)<>24 OR NEW.serial<>COALESCE((SELECT max(serial)+1 FROM training_sessions WHERE plan_id=NEW.plan_id),1) OR NOT EXISTS(SELECT 1 FROM training_plan_current p JOIN visits v ON v.id=NEW.visit_id JOIN visit_cycle_versions r ON r.visit_id=v.id AND r.cycle_id=p.cycle_id WHERE p.id=NEW.plan_id AND p.status='active' AND p.version=NEW.plan_version AND p.revision=NEW.plan_revision AND p.customer_id=NEW.customer_id AND p.store_id=NEW.store_id AND p.cycle_id=NEW.cycle_id AND r.customer_id=NEW.customer_id AND r.basis='captured' AND r.version=NEW.visit_cycle_version AND v.status='registered' AND NEW.created_at>=v.created_at AND NEW.created_at>=p.event_created_at) OR EXISTS(SELECT 1 FROM training_plan_attachments r JOIN attachments a ON a.id=r.attachment_id WHERE r.plan_id=NEW.plan_id AND r.version=NEW.plan_version AND a.revoked_at IS NOT NULL) THEN RAISE(ABORT,'training session source invalid') END;END;
CREATE TRIGGER training_session_event_ready BEFORE INSERT ON training_session_events BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security sec ON sec.user_id=u.id WHERE u.id=NEW.created_by AND u.active=1 AND u.store_id=(SELECT store_id FROM training_plans WHERE id=NEW.plan_id) AND COALESCE(sec.must_change_password,0)=0 AND u.role IN('manager','reception','professional')) OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR length(NEW.created_at)<>24 OR NEW.revision<>COALESCE((SELECT max(revision)+1 FROM training_session_events WHERE session_id=NEW.session_id),1) OR NEW.sequence<>COALESCE((SELECT max(sequence)+1 FROM training_session_events WHERE plan_id=NEW.plan_id),1) OR NEW.plan_revision<>(SELECT max(revision) FROM training_plan_events WHERE plan_id=NEW.plan_id) OR NOT EXISTS(SELECT 1 FROM training_sessions WHERE id=NEW.session_id AND plan_id=NEW.plan_id) OR NEW.created_at<COALESCE((SELECT max(created_at) FROM training_session_events WHERE plan_id=NEW.plan_id),'') OR NEW.created_at<(SELECT created_at FROM training_plan_events WHERE plan_id=NEW.plan_id AND revision=NEW.plan_revision) OR NEW.action IN('create','assign','start','resume','record','correct') AND NOT EXISTS(SELECT 1 FROM users u LEFT JOIN user_security s ON s.user_id=u.id WHERE u.id=NEW.assignee_id AND u.role='professional' AND u.active=1 AND u.store_id=(SELECT store_id FROM training_plans WHERE id=NEW.plan_id) AND COALESCE(s.must_change_password,0)=0) THEN RAISE(ABORT,'training session event source invalid') END;
 SELECT CASE WHEN NOT(NEW.action='create' AND NEW.revision=1 AND NEW.status='ready' AND NEW.created_at=(SELECT created_at FROM training_sessions WHERE id=NEW.session_id) AND NEW.created_by=(SELECT created_by FROM training_sessions WHERE id=NEW.session_id) OR NEW.action='assign' AND (SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)='ready' AND NEW.status='ready' OR NEW.action='start' AND (SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)='ready' AND NEW.status='running' OR NEW.action='pause' AND (SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)='running' AND NEW.status='paused' OR NEW.action='resume' AND (SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)='paused' AND NEW.status='running' OR NEW.action='record' AND (SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)='running' AND NEW.status='recorded' OR NEW.action='correct' AND (SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)='recorded' AND NEW.status='recorded' OR NEW.action='confirm' AND (SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)='recorded' AND NEW.status='reviewed' OR NEW.action='abort' AND (SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1) IN('ready','running','paused') AND NEW.status='aborted' OR NEW.action='note' AND NEW.revision>1 AND NEW.status=(SELECT status FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)) OR (NEW.action NOT IN('create','assign') AND NEW.assignee_id IS NOT (SELECT assignee_id FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)) OR (NEW.action NOT IN('create','start') AND NEW.started_at IS NOT (SELECT started_at FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)) OR (NEW.action NOT IN('record','correct') AND NEW.manifest_json IS NOT (SELECT manifest_json FROM training_session_events WHERE session_id=NEW.session_id ORDER BY revision DESC LIMIT 1)) OR (NEW.action='create' AND (NEW.started_at IS NOT NULL OR NEW.manifest_json IS NOT NULL)) THEN RAISE(ABORT,'training session transition invalid') END;
 SELECT CASE WHEN (NEW.action IN('start','pause','resume','record','correct') AND (NEW.created_by<>NEW.assignee_id OR (SELECT role FROM users WHERE id=NEW.created_by)<>'professional')) OR (NEW.action='confirm' AND (NEW.created_by<>(SELECT v.owner_id FROM training_sessions s JOIN training_plan_versions v ON v.plan_id=s.plan_id AND v.version=s.plan_version WHERE s.id=NEW.session_id) OR (SELECT role FROM users WHERE id=NEW.created_by)<>'professional')) OR (NEW.action='abort' AND (SELECT role FROM users WHERE id=NEW.created_by)<>'manager' AND NEW.created_by<>NEW.assignee_id) THEN RAISE(ABORT,'training session actor invalid') END;
 SELECT CASE WHEN (NEW.action IN('start','resume') AND ((SELECT status FROM training_plan_current WHERE id=NEW.plan_id)<>'active' OR (SELECT status FROM visits WHERE id=(SELECT visit_id FROM training_sessions WHERE id=NEW.session_id))<>'registered' OR (NEW.action='start' AND (SELECT plan_version FROM training_sessions WHERE id=NEW.session_id)<>(SELECT version FROM training_plan_current WHERE id=NEW.plan_id)))) OR (NEW.action='record' AND (SELECT status FROM training_plan_current WHERE id=NEW.plan_id) NOT IN('active','draft')) OR (NEW.action IN('start','resume','confirm') AND EXISTS(SELECT 1 FROM training_plan_attachments r JOIN attachments a ON a.id=r.attachment_id JOIN training_sessions s ON s.id=NEW.session_id AND s.plan_id=r.plan_id AND s.plan_version=r.version WHERE a.revoked_at IS NOT NULL)) THEN RAISE(ABORT,'training plan or visit held') END;
 SELECT CASE WHEN NEW.started_at IS NOT NULL AND (strftime('%Y-%m-%dT%H:%M:%fZ',NEW.started_at) IS NOT NEW.started_at OR length(NEW.started_at)<>24 OR NEW.started_at>NEW.created_at) OR NEW.action='start' AND NEW.started_at IS NULL OR NEW.action IN('record','correct') AND (NEW.manifest_json IS NULL OR json_type(NEW.manifest_json,'$.items') IS NOT 'array' OR json_array_length(NEW.manifest_json,'$.items')<>(SELECT count(*) FROM training_plan_items i JOIN training_sessions s ON s.id=NEW.session_id AND s.plan_id=i.plan_id AND s.plan_version=i.version) OR json_extract(NEW.manifest_json,'$.ended_at')<NEW.started_at OR json_extract(NEW.manifest_json,'$.ended_at')>NEW.created_at OR strftime('%Y-%m-%dT%H:%M:%fZ',json_extract(NEW.manifest_json,'$.ended_at')) IS NOT json_extract(NEW.manifest_json,'$.ended_at') OR length(json_extract(NEW.manifest_json,'$.ended_at'))<>24) THEN RAISE(ABORT,'training actual record invalid') END;
END;
CREATE TRIGGER training_projects_no_update BEFORE UPDATE ON training_projects BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_projects_no_delete BEFORE DELETE ON training_projects BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_project_versions_no_update BEFORE UPDATE ON training_project_versions BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_project_versions_no_delete BEFORE DELETE ON training_project_versions BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plans_no_update BEFORE UPDATE ON training_plans BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plans_no_delete BEFORE DELETE ON training_plans BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plan_versions_no_update BEFORE UPDATE ON training_plan_versions BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plan_versions_no_delete BEFORE DELETE ON training_plan_versions BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plan_items_no_update BEFORE UPDATE ON training_plan_items BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plan_items_no_delete BEFORE DELETE ON training_plan_items BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plan_documents_no_update BEFORE UPDATE ON training_plan_documents BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plan_documents_no_delete BEFORE DELETE ON training_plan_documents BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plan_attachments_no_update BEFORE UPDATE ON training_plan_attachments BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_plan_attachments_no_delete BEFORE DELETE ON training_plan_attachments BEGIN SELECT RAISE(ABORT,'training immutable');END;
