CREATE TRIGGER training_plan_events_no_delete BEFORE DELETE ON training_plan_events BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_sessions_no_update BEFORE UPDATE ON training_sessions BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_sessions_no_delete BEFORE DELETE ON training_sessions BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_session_events_no_update BEFORE UPDATE ON training_session_events BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_session_events_no_delete BEFORE DELETE ON training_session_events BEGIN SELECT RAISE(ABORT,'training immutable');END;
CREATE TRIGGER training_session_actual_ready BEFORE INSERT ON training_session_events WHEN NEW.action IN('record','correct') BEGIN
 SELECT CASE WHEN (SELECT count(*) FROM json_each(NEW.manifest_json))<>5 OR json_type(NEW.manifest_json,'$.items') IS NOT 'array' OR json_type(NEW.manifest_json,'$.feedback') IS NOT 'text' OR length(trim(json_extract(NEW.manifest_json,'$.feedback'))) NOT BETWEEN 1 AND 1000 OR json_type(NEW.manifest_json,'$.additional_activity') IS NULL OR json_type(NEW.manifest_json,'$.additional_activity') NOT IN('text','null') OR length(json_extract(NEW.manifest_json,'$.additional_activity'))>1000 OR json_type(NEW.manifest_json,'$.actual_minutes') IS NULL OR json_type(NEW.manifest_json,'$.actual_minutes') NOT IN('integer','null') OR json_extract(NEW.manifest_json,'$.actual_minutes') NOT BETWEEN 0 AND 1440 OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.items') x WHERE (SELECT count(*) FROM json_each(x.value))<>4 OR json_type(x.value,'$.position') IS NOT 'integer' OR json_type(x.value,'$.completion') IS NOT 'text' OR json_extract(x.value,'$.completion') NOT IN('completed','partial','not_done','unknown') OR json_type(x.value,'$.feedback') IS NOT 'text' OR length(trim(json_extract(x.value,'$.feedback'))) NOT BETWEEN 1 AND 1000 OR json_type(x.value,'$.actual_minutes') IS NULL OR json_type(x.value,'$.actual_minutes') NOT IN('integer','null') OR json_extract(x.value,'$.actual_minutes') NOT BETWEEN 0 AND 1440 OR NOT EXISTS(SELECT 1 FROM training_plan_items i JOIN training_sessions s ON s.id=NEW.session_id AND s.plan_id=i.plan_id AND s.plan_version=i.version WHERE i.position=json_extract(x.value,'$.position'))) OR EXISTS(SELECT 1 FROM json_each(NEW.manifest_json,'$.items') x GROUP BY json_extract(x.value,'$.position') HAVING count(*)>1) THEN RAISE(ABORT,'training actual fields invalid') END;
END;
